    // We'll just set the first 6 characters to the filename "test"
    for (int i = 0; i < 6; i++) {
        tarHeader[i] = 't';
        tarHeader[i+1] = 'e';
        tarHeader[i+2] = 's';
        tarHeader[i+3] = 't';
